<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-btn v-if="can('store.manage')" block class="mb-3" prepend-icon="mdi-store-plus-outline" @click="dialog=true">점포 등록</v-btn><v-list lines="three"><v-list-item v-for="s in stores" :key="s.id" :title="s.name" :subtitle="`${s.store_code} · ${s.status} · 출퇴근 반경 ${s.attendance_radius_meters}m`"><template #prepend><v-icon icon="mdi-store-outline"/></template></v-list-item></v-list><v-dialog v-model="dialog" max-width="400"><v-card title="점포 등록"><v-card-text><v-text-field v-model="form.store_code" label="점포 코드" variant="outlined"/><v-text-field v-model="form.name" label="점포명" variant="outlined"/><v-text-field v-model="form.phone" label="전화번호" variant="outlined"/><v-text-field v-model="form.address" label="주소" variant="outlined"/><v-number-input v-model="form.attendance_radius_meters" label="출퇴근 허용 반경(m)" :min="10" variant="outlined"/><v-select v-model="form.status" :items="['active','inactive','closed']" label="상태" variant="outlined"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">취소</v-btn><v-btn @click="save(setError)">저장</v-btn></v-card-actions></v-card></v-dialog></template></AppShell></template>
<script setup>
import{onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='점포 관리';const stores=ref([]),dialog=ref(false);const form=ref({store_code:'',name:'',phone:'',address:'',attendance_radius_meters:100,status:'active'});async function load(){stores.value=(await window.axios.get('/tillwhite/api/stores')).data.stores;}async function save(err){try{await window.axios.post('/tillwhite/api/stores',form.value);dialog.value=false;await load();}catch(e){err(e.response?.data?.message??'점포 저장 실패');}}onMounted(load);
</script>
